/*  Constants                                                          */
/* ================================================================== */

const MIN_OFFICE_W = 600;
const CEO_ZONE_H = 110;
const HALLWAY_H = 32;
const TARGET_CHAR_H = 52;
const MINI_CHAR_H = 28;
const CEO_SIZE = 44;
const DESK_W = 48;
const DESK_H = 26;
const SLOT_W = 180;
const SLOT_H = 280;
const COLS_PER_ROW = 3;
const ROOM_PAD = 16;
const TILE = 20;
const CEO_SPEED = 7;
const DELIVERY_SPEED = 0.012;

const BREAK_ROOM_H = 360;
const BREAK_ROOM_GAP = 32;
const MAX_VISIBLE_SUB_CLONES_PER_AGENT = 3;
const SUB_CLONE_WAVE_SPEED = 0.04;
const SUB_CLONE_MOVE_X_AMPLITUDE = 0.16;
const SUB_CLONE_MOVE_Y_AMPLITUDE = 0.34;
const SUB_CLONE_FLOAT_DRIFT = 0.08;
const SUB_CLONE_FIREWORK_INTERVAL = 210;
const MOBILE_MOVE_CODES = {
  up: ["ArrowUp", "KeyW"],
  down: ["ArrowDown", "KeyS"],
  left: ["ArrowLeft", "KeyA"],
  right: ["ArrowRight", "KeyD"],
} as const;
type MobileMoveDirection = keyof typeof MOBILE_MOVE_CODES;
type RoomTheme = { floor1: number; floor2: number; wall: number; accent: number };

type SubCloneBurstParticle = {
  node: Container;
  vx: number;
  vy: number;
  life: number;
  maxLife: number;
  spin: number;
  growth: number;
};

function emitSubCloneSmokeBurst(
  target: Container,
  particles: SubCloneBurstParticle[],
  x: number,
  y: number,
  mode: "spawn" | "despawn",
): void {
  const baseColor = mode === "spawn" ? 0xc7d4ec : 0xb7bfd1;
  const strokeColor = mode === "spawn" ? 0xe6edff : 0xd4dae8;
  const puffCount = mode === "spawn" ? 9 : 7;
  for (let i = 0; i < puffCount; i++) {
    const puff = new Graphics();
    const radius = 1.8 + Math.random() * 2.8;
    puff.circle(0, 0, radius).fill({ color: baseColor, alpha: 0.62 + Math.random() * 0.18 });
    puff.circle(0, 0, radius).stroke({ width: 0.6, color: strokeColor, alpha: 0.32 });
    puff.position.set(x + (Math.random() - 0.5) * 10, y - 14 + (Math.random() - 0.5) * 6);
    target.addChild(puff);
    particles.push({
      node: puff,
      vx: (Math.random() - 0.5) * (mode === "spawn" ? 1.4 : 1.1),
      vy: -0.22 - Math.random() * 0.6,
      life: 0,
      maxLife: 20 + Math.floor(Math.random() * 12),
      spin: (Math.random() - 0.5) * 0.1,
      growth: 0.013 + Math.random() * 0.012,
    });
  }

  const flash = new Graphics();
  flash.circle(0, 0, mode === "spawn" ? 5.4 : 4.2).fill({ color: 0xf8fbff, alpha: mode === "spawn" ? 0.52 : 0.42 });
  flash.position.set(x, y - 14);
  target.addChild(flash);
  particles.push({
    node: flash,
    vx: 0,
    vy: -0.16,
    life: 0,
    maxLife: mode === "spawn" ? 14 : 12,
    spin: 0,
    growth: 0.022,
  });

  const burstTxt = new Text({
    text: "펑",
    style: new TextStyle({
      fontSize: 7,
      fill: mode === "spawn" ? 0xeff4ff : 0xdde4f5,
      fontWeight: "bold",
      fontFamily: "system-ui, sans-serif",
      stroke: { color: 0x1f2838, width: 2 },
    }),
  });
  burstTxt.anchor.set(0.5, 0.5);
  burstTxt.position.set(x, y - 24);
  target.addChild(burstTxt);
  particles.push({
    node: burstTxt,
    vx: (Math.random() - 0.5) * 0.35,
    vy: -0.3,
    life: 0,
    maxLife: mode === "spawn" ? 18 : 16,
    spin: (Math.random() - 0.5) * 0.04,
    growth: 0.004,
  });
}

function emitSubCloneFireworkBurst(target: Container, particles: SubCloneBurstParticle[], x: number, y: number): void {
  const colors = [0xff6b6b, 0xffc75f, 0x7ce7ff, 0x8cff9f, 0xd7a6ff];
  const sparkCount = 10;
  for (let i = 0; i < sparkCount; i++) {
    const spark = new Graphics();
    const color = colors[Math.floor(Math.random() * colors.length)];
    const radius = 0.85 + Math.random() * 0.6;
    spark.circle(0, 0, radius).fill({ color, alpha: 0.96 });
    spark.circle(0, 0, radius).stroke({ width: 0.45, color: 0xffffff, alpha: 0.5 });
    spark.position.set(x + (Math.random() - 0.5) * 5, y + (Math.random() - 0.5) * 3);
    target.addChild(spark);
    const angle = (Math.PI * 2 * i) / sparkCount + (Math.random() - 0.5) * 0.45;
    const speed = 0.9 + Math.random() * 0.85;
    particles.push({
      node: spark,
      vx: Math.cos(angle) * speed,
      vy: Math.sin(angle) * speed - 0.45,
      life: 0,
      maxLife: 16 + Math.floor(Math.random() * 8),
      spin: (Math.random() - 0.5) * 0.08,
      growth: 0.006 + Math.random() * 0.006,
    });
  }
}

export {
  type OfficeViewProps,
  type Delivery,
  type RoomRect,
  type WallClockVisual,
  detachNode,
  destroyNode,
  trackProcessedId,
  type ScrollAxis,
  canScrollOnAxis,
  findScrollContainer,
  MIN_OFFICE_W,
  CEO_ZONE_H,
  HALLWAY_H,
  TARGET_CHAR_H,
  MINI_CHAR_H,
  CEO_SIZE,
  DESK_W,
  DESK_H,
  SLOT_W,
  SLOT_H,
  COLS_PER_ROW,
  ROOM_PAD,
  TILE,
  CEO_SPEED,
  DELIVERY_SPEED,
  BREAK_ROOM_H,
  BREAK_ROOM_GAP,
  MAX_VISIBLE_SUB_CLONES_PER_AGENT,
  SUB_CLONE_WAVE_SPEED,
  SUB_CLONE_MOVE_X_AMPLITUDE,
  SUB_CLONE_MOVE_Y_AMPLITUDE,
  SUB_CLONE_FLOAT_DRIFT,
  SUB_CLONE_FIREWORK_INTERVAL,
  MOBILE_MOVE_CODES,
  type MobileMoveDirection,
  type RoomTheme,
  type SubCloneBurstParticle,
  emitSubCloneSmokeBurst,
  emitSubCloneFireworkBurst,
};

import type { MutableRefObject } from "react";
import { Container, Graphics, Text, TextStyle, type Application, type Texture } from "pixi.js";
import type { Agent, Department, SubAgent, Task } from "../../types";
import { localeName } from "../../i18n";
import type { CallbackSnapshot, AnimItem, SubCloneAnimItem } from "./buildScene-types";
import {
  COLS_PER_ROW,
  DESK_W,
  ROOM_PAD,
  SLOT_H,
  SLOT_W,
  TARGET_CHAR_H,
  type RoomRect,
  type SubCloneBurstParticle,
  type WallClockVisual,
  emitSubCloneSmokeBurst,
} from "./model";
import { DEPT_THEME, LOCALE_TEXT, type SupportedLocale, pickLocale } from "./themes-locale";
import {
  blendColor,
  contrastTextColor,
  drawAmbientGlow,
  drawBunting,
  drawCeilingLight,
  drawPictureFrame,
  drawRug,
  drawRoomAtmosphere,
  drawTiledFloor,
  drawTrashCan,
  drawWallClock,
  drawWindow,
} from "./drawing-core";
import { drawChair, drawDesk, drawPlant, drawWhiteboard } from "./drawing-furniture-a";
import { drawBookshelf } from "./drawing-furniture-b";
import { renderDeskAgentAndSubClones } from "./buildScene-department-agent";

interface BuildDepartmentRoomsParams {
  app: Application;
  textures: Record<string, Texture>;
  departments: Department[];
  agents: Agent[];
  tasks: Task[];
  subAgents: SubAgent[];
  unread?: Set<string>;
  customThemes?: Record<string, { floor1: number; floor2: number; wall: number; accent: number }>;
  activeLocale: SupportedLocale;
  gridCols: number;
  roomStartX: number;
  roomW: number;
  roomH: number;
  roomGap: number;
  deptStartY: number;
  agentRows: number;
  spriteMap: Map<string, number>;
  cbRef: MutableRefObject<CallbackSnapshot>;
  roomRectsRef: MutableRefObject<RoomRect[]>;
  agentPosRef: MutableRefObject<Map<string, { x: number; y: number }>>;
  animItemsRef: MutableRefObject<AnimItem[]>;
  subCloneAnimItemsRef: MutableRefObject<SubCloneAnimItem[]>;
  subCloneBurstParticlesRef: MutableRefObject<SubCloneBurstParticle[]>;
  wallClocksRef: MutableRefObject<WallClockVisual[]>;
  removedSubBurstsByParent: Map<string, Array<{ x: number; y: number }>>;
  addedWorkingSubIds: Set<string>;
  nextSubSnapshot: Map<string, { parentAgentId: string; x: number; y: number }>;
}

export function buildDepartmentRooms({
  app,
  textures,
  departments,
  agents,
  tasks,
  subAgents,
  unread,
  customThemes,
  activeLocale,
  gridCols,
  roomStartX,
  roomW,
  roomH,
  roomGap,
  deptStartY,
  agentRows,
  spriteMap,
  cbRef,
  roomRectsRef,
  agentPosRef,
  animItemsRef,
  subCloneAnimItemsRef,
  subCloneBurstParticlesRef,
  wallClocksRef,
  removedSubBurstsByParent,
  addedWorkingSubIds,
  nextSubSnapshot,
}: BuildDepartmentRoomsParams): void {
  departments.forEach((dept, deptIdx) => {
    const col = deptIdx % gridCols;
    const row = Math.floor(deptIdx / gridCols);
    const rx = roomStartX + col * (roomW + roomGap);
    const ry = deptStartY + row * (roomH + roomGap);
    const theme = customThemes?.[dept.id] || DEPT_THEME[dept.id] || DEPT_THEME.dev;
    const deptAgents = agents.filter((agent) => agent.department_id === dept.id);
    roomRectsRef.current.push({ dept, x: rx, y: ry, w: roomW, h: roomH });

    const room = new Container();

    const floorG = new Graphics();
    drawTiledFloor(floorG, rx, ry, roomW, roomH, theme.floor1, theme.floor2);
    room.addChild(floorG);
    drawRoomAtmosphere(room, rx, ry, roomW, roomH, theme.wall, theme.accent);

    const wallG = new Graphics();
    wallG.roundRect(rx, ry, roomW, roomH, 3).stroke({ width: 2.5, color: theme.wall });
    room.addChild(wallG);

    const doorG = new Graphics();
    doorG.rect(rx + roomW / 2 - 16, ry - 2, 32, 5).fill(0xf5f0e8);
    room.addChild(doorG);

    const signW = 84;
    const signBg = new Graphics();
    signBg.roundRect(rx + roomW / 2 - signW / 2 + 1, ry - 3, signW, 18, 4).fill({ color: 0x000000, alpha: 0.12 });
    signBg.roundRect(rx + roomW / 2 - signW / 2, ry - 4, signW, 18, 4).fill(theme.accent);
    signBg.eventMode = "static";
    signBg.cursor = "pointer";
    signBg.on("pointerdown", () => cbRef.current.onSelectDepartment(dept));
    room.addChild(signBg);
    const signTxt = new Text({
      text: `${dept.icon || "🏢"} ${localeName(activeLocale, dept)}`,
      style: new TextStyle({
        fontSize: 9,
        fill: 0xffffff,
        fontWeight: "bold",
        fontFamily: "system-ui, sans-serif",
        dropShadow: { alpha: 0.2, distance: 1, color: 0x000000 },
      }),
    });
    signTxt.anchor.set(0.5, 0.5);
    signTxt.position.set(rx + roomW / 2, ry + 5);
    room.addChild(signTxt);

    drawCeilingAndDecor(room, rx, ry, roomW, roomH, theme, deptIdx, wallClocksRef);

    if (deptAgents.length > 0) {
      drawRug(
        room,
        rx + roomW / 2,
        ry + 38 + (Math.min(agentRows, 2) * SLOT_H) / 2,
        roomW - 40,
        Math.min(agentRows, 2) * SLOT_H - 10,
        theme.accent,
      );
    }

    if (deptAgents.length === 0) {
      const emptyText = new Text({
        text: pickLocale(activeLocale, LOCALE_TEXT.noAssignedAgent),
        style: new TextStyle({ fontSize: 10, fill: 0x9a8a7a, fontFamily: "system-ui, sans-serif" }),
      });
      emptyText.anchor.set(0.5, 0.5);
      emptyText.position.set(rx + roomW / 2, ry + roomH / 2);
      room.addChild(emptyText);
    }

    deptAgents.forEach((agent, agentIdx) => {
      const acol = agentIdx % COLS_PER_ROW;
      const arow = Math.floor(agentIdx / COLS_PER_ROW);
      const ax = rx + ROOM_PAD + acol * SLOT_W + SLOT_W / 2;
      const ay = ry + 164 + arow * SLOT_H;
      const isWorking = agent.status === "working";
      const isOffline = agent.status === "offline";
      const isBreak = agent.status === "break";

      const nameY = ay;
      const charFeetY = nameY + 54 + TARGET_CHAR_H;
      const deskY = charFeetY - 8;

      agentPosRef.current.set(agent.id, { x: ax, y: deskY });

      renderAgentHeader(room, ax, nameY, agent, theme.accent, unread, activeLocale);
      drawChair(room, ax, charFeetY - TARGET_CHAR_H * 0.18, theme.accent);

      const removedBursts = removedSubBurstsByParent.get(agent.id);
      if (removedBursts && removedBursts.length > 0) {
        for (const burst of removedBursts) {
          emitSubCloneSmokeBurst(room, subCloneBurstParticlesRef.current, burst.x, burst.y, "despawn");
        }
        removedSubBurstsByParent.delete(agent.id);
      }

      if (isBreak) {
        drawBreakAwayTag(room, ax, deskY, charFeetY, activeLocale, theme.accent);
      } else {
        renderDeskAgentAndSubClones({
          room,
          textures,
          spriteMap,
          agent,
          tasks,
          subAgents,
          ax,
          deskY,
          charFeetY,
          isWorking,
          isOffline,
          cbRef,
          animItemsRef,
          subCloneAnimItemsRef,
          subCloneBurstParticlesRef,
          addedWorkingSubIds,
          nextSubSnapshot,
          themeAccent: theme.accent,
        });
      }
    });

    app.stage.addChild(room);
  });
}

function drawCeilingAndDecor(
  room: Container,
  rx: number,
  ry: number,
  roomW: number,
  roomH: number,
  theme: { accent: number; wall: number },
  deptIdx: number,
  wallClocksRef: MutableRefObject<WallClockVisual[]>,
): void {
  drawCeilingLight(room, rx + roomW / 2, ry + 14, theme.accent);
  drawAmbientGlow(room, rx + roomW / 2, ry + roomH / 2, roomW * 0.4, theme.accent, 0.04);
  drawBunting(
    room,
    rx + 12,
    ry + 16,
    roomW - 24,
    blendColor(theme.accent, 0xffffff, 0.2),
    blendColor(theme.wall, 0xffffff, 0.4),
    0.52,
  );

  drawWhiteboard(room, rx + roomW - 48, ry + 18);
  drawBookshelf(room, rx + 6, ry + 18);
  wallClocksRef.current.push(drawWallClock(room, rx + roomW - 16, ry + 12));
  drawWindow(room, rx + roomW / 2 - 12, ry + 16);
  if (roomW > 240) {
    drawWindow(room, rx + roomW / 2 - 40, ry + 16, 20, 16);
    drawWindow(room, rx + roomW / 2 + 20, ry + 16, 20, 16);
  }
  if (roomW > 200) {
    drawPictureFrame(room, rx + 40, ry + 20);
  }

  drawPlant(room, rx + 8, ry + roomH - 14, deptIdx);
  drawPlant(room, rx + roomW - 12, ry + roomH - 14, deptIdx + 1);
  drawTrashCan(room, rx + roomW - 14, ry + roomH - 26);
}

function renderAgentHeader(
  room: Container,
  ax: number,
  nameY: number,
  agent: Agent,
  accent: number,
  unread: Set<string> | undefined,
  activeLocale: SupportedLocale,
): void {
  const nameText = new Text({
    text: localeName(activeLocale, agent),
    style: new TextStyle({
      fontSize: 22,
      fill: 0x3a3a4a,
      fontWeight: "bold",
      fontFamily: "system-ui, sans-serif",
    }),
  });
  nameText.anchor.set(0.5, 0);
  const nameTagW = nameText.width + 10;
  const nameTagBg = new Graphics();
  nameTagBg.roundRect(ax - nameTagW / 2, nameY, nameTagW, 34, 4).fill({ color: 0xffffff, alpha: 0.85 });
  room.addChild(nameTagBg);
  nameText.position.set(ax, nameY + 2);
  room.addChild(nameText);

  if (unread?.has(agent.id)) {
    const bangBg = new Graphics();
    const bangX = ax + nameTagW / 2 + 2;
    bangBg.circle(bangX, nameY + 17, 6).fill(0xff3333);
    bangBg.circle(bangX, nameY + 17, 6).stroke({ width: 1, color: 0xff0000, alpha: 0.6 });
    room.addChild(bangBg);
    const bangTxt = new Text({
      text: "!",
      style: new TextStyle({ fontSize: 8, fill: 0xffffff, fontWeight: "bold", fontFamily: "monospace" }),
    });
    bangTxt.anchor.set(0.5, 0.5);
    bangTxt.position.set(bangX, nameY + 17);
    room.addChild(bangTxt);
  }

  const roleText = new Text({
    text: pickLocale(
      activeLocale,
      LOCALE_TEXT.role[agent.role as keyof typeof LOCALE_TEXT.role] || {
        ko: agent.role,
        en: agent.role,
        ja: agent.role,
        zh: agent.role,
      },
    ),
    style: new TextStyle({
      fontSize: 8,
      fill: contrastTextColor(accent),
      fontFamily: "system-ui, sans-serif",
    }),
  });
  roleText.anchor.set(0.5, 0.5);
  const roleTagW = roleText.width + 5;
  const roleTagBg = new Graphics();
  roleTagBg.roundRect(ax - roleTagW / 2, nameY + 36, roleTagW, 12, 2).fill({ color: accent, alpha: 0.82 });
  room.addChild(roleTagBg);
  roleText.position.set(ax, nameY + 42);
  room.addChild(roleText);
}

function drawBreakAwayTag(
  room: Container,
  ax: number,
  deskY: number,
  charFeetY: number,
  activeLocale: SupportedLocale,
  accent: number,
): void {
  drawDesk(room, ax - DESK_W / 2, deskY, false);
  const awayTagY = charFeetY - TARGET_CHAR_H / 2;
  const awayTagBgColor = blendColor(accent, 0x101826, 0.78);
  const awayTag = new Text({
    text: pickLocale(activeLocale, LOCALE_TEXT.breakRoom),
    style: new TextStyle({
      fontSize: 8,
      fill: contrastTextColor(awayTagBgColor),
      fontWeight: "bold",
      fontFamily: "system-ui, sans-serif",
    }),
  });
  awayTag.anchor.set(0.5, 0.5);
  const awayTagW = awayTag.width + 10;
  const awayTagH = awayTag.height + 4;
  const awayTagBg = new Graphics();
  awayTagBg
    .roundRect(ax - awayTagW / 2, awayTagY - awayTagH / 2, awayTagW, awayTagH, 3)
    .fill({ color: awayTagBgColor, alpha: 0.9 });
  awayTagBg
    .roundRect(ax - awayTagW / 2, awayTagY - awayTagH / 2, awayTagW, awayTagH, 3)
    .stroke({ width: 1, color: blendColor(accent, 0xffffff, 0.2), alpha: 0.85 });
  room.addChild(awayTagBg);
  awayTag.position.set(ax, awayTagY + 0.5);
  room.addChild(awayTag);
}

import type { MutableRefObject } from "react";
import { AnimatedSprite, Container, Graphics, Sprite, Text, TextStyle, type Texture } from "pixi.js";
import type { Agent, SubAgent, Task } from "../../types";
import type { AnimItem, CallbackSnapshot, SubCloneAnimItem } from "./buildScene-types";
import {
  DESK_W,
  MAX_VISIBLE_SUB_CLONES_PER_AGENT,
  SUB_CLONE_FIREWORK_INTERVAL,
  TARGET_CHAR_H,
  type SubCloneBurstParticle,
  emitSubCloneFireworkBurst,
  emitSubCloneSmokeBurst,
} from "./model";
import { hashStr } from "./drawing-core";
import { drawDesk } from "./drawing-furniture-a";

interface RenderDeskAgentAndSubClonesParams {
  room: Container;
  textures: Record<string, Texture>;
  spriteMap: Map<string, number>;
  agent: Agent;
  tasks: Task[];
  subAgents: SubAgent[];
  ax: number;
  deskY: number;
  charFeetY: number;
  isWorking: boolean;
  isOffline: boolean;
  cbRef: MutableRefObject<CallbackSnapshot>;
  animItemsRef: MutableRefObject<AnimItem[]>;
  subCloneAnimItemsRef: MutableRefObject<SubCloneAnimItem[]>;
  subCloneBurstParticlesRef: MutableRefObject<SubCloneBurstParticle[]>;
  addedWorkingSubIds: Set<string>;
  nextSubSnapshot: Map<string, { parentAgentId: string; x: number; y: number }>;
  themeAccent: number;
}

export function renderDeskAgentAndSubClones({
  room,
  textures,
  spriteMap,
  agent,
  tasks,
  subAgents,
  ax,
  deskY,
  charFeetY,
  isWorking,
  isOffline,
  cbRef,
  animItemsRef,
  subCloneAnimItemsRef,
  subCloneBurstParticlesRef,
  addedWorkingSubIds,
  nextSubSnapshot,
  themeAccent,
}: RenderDeskAgentAndSubClonesParams): void {
  const spriteNum = spriteMap.get(agent.id) ?? (hashStr(agent.id) % 13) + 1;
  const charContainer = new Container();
  charContainer.position.set(ax, charFeetY);
  charContainer.eventMode = "static";
  charContainer.cursor = "pointer";
  charContainer.on("pointerdown", () => cbRef.current.onSelectAgent(agent));

  const frames: Texture[] = [];
  for (let frame = 1; frame <= 3; frame++) {
    const key = `${spriteNum}-D-${frame}`;
    if (textures[key]) frames.push(textures[key]);
  }

  if (frames.length > 0) {
    const animSprite = new AnimatedSprite(frames);
    animSprite.anchor.set(0.5, 1);
    const scale = TARGET_CHAR_H / animSprite.texture.height;
    animSprite.scale.set(scale);
    animSprite.gotoAndStop(0);
    if (isOffline) {
      animSprite.alpha = 0.3;
      animSprite.tint = 0x888899;
    }
    charContainer.addChild(animSprite);
  } else {
    const fallback = new Text({ text: agent.avatar_emoji || "🤖", style: new TextStyle({ fontSize: 24 }) });
    fallback.anchor.set(0.5, 1);
    charContainer.addChild(fallback);
  }
  room.addChild(charContainer);

  const deskG = drawDesk(room, ax - DESK_W / 2, deskY, isWorking);

  const bedW = TARGET_CHAR_H + 20;
  const bedH = 36;
  const bedX = ax - bedW / 2;
  const bedY = deskY;

  const bedG = new Graphics();
  bedG.roundRect(bedX, bedY, bedW, bedH, 4).fill(0x5c3d2e);
  bedG.roundRect(bedX + 1, bedY + 1, bedW - 2, bedH - 2, 3).fill(0x8b6347);
  bedG.roundRect(bedX + 3, bedY + 3, bedW - 6, bedH - 6, 2).fill(0xf0e6d3);
  bedG.roundRect(bedX - 2, bedY - 1, 6, bedH + 2, 3).fill(0x4a2e1a);
  bedG.ellipse(bedX + 16, bedY + bedH / 2, 9, 7).fill(0xfff8ee);
  bedG.ellipse(bedX + 16, bedY + bedH / 2, 9, 7).stroke({ width: 0.5, color: 0xd8d0c0 });
  bedG.ellipse(bedX + 16, bedY + bedH / 2, 5, 4).fill({ color: 0xf0e8d8, alpha: 0.6 });
  bedG.visible = false;
  room.addChild(bedG);

  const blanketG = new Graphics();
  const blanketX = bedX + bedW * 0.35;
  const blanketW = bedW * 0.62;
  blanketG.roundRect(blanketX, bedY + 2, blanketW, bedH - 4, 3).fill(0xc8d8be);
  blanketG.roundRect(blanketX, bedY + 2, blanketW, bedH - 4, 3).stroke({ width: 0.5, color: 0xa8b898 });
  blanketG
    .moveTo(blanketX + 2, bedY + bedH / 2)
    .lineTo(blanketX + blanketW - 4, bedY + bedH / 2)
    .stroke({ width: 0.4, color: 0xb0c0a0, alpha: 0.5 });
  blanketG.visible = false;
  room.addChild(blanketG);

  const particles = new Container();
  room.addChild(particles);
  animItemsRef.current.push({
    sprite: charContainer,
    status: agent.status,
    baseX: ax,
    baseY: charContainer.position.y,
    particles,
    agentId: agent.id,
    cliProvider: agent.cli_provider,
    deskG,
    bedG,
    blanketG,
  });

  const activeTask = tasks.find((task) => task.assigned_agent_id === agent.id && task.status === "in_progress");
  if (activeTask) {
    const txt = activeTask.title.length > 16 ? `${activeTask.title.slice(0, 16)}...` : activeTask.title;
    const bubbleText = new Text({
      text: `💬 ${txt}`,
      style: new TextStyle({
        fontSize: 24,
        fill: 0x333333,
        fontFamily: "system-ui, sans-serif",
        wordWrap: true,
        wordWrapWidth: 160,
        breakWords: true,
      }),
    });
    bubbleText.anchor.set(0.5, 1);
    const bw = bubbleText.width + 20;
    const bh = bubbleText.height + 16;
    const bubbleTop = charFeetY - TARGET_CHAR_H - bh - 64;
    const bubbleG = new Graphics();
    bubbleG.roundRect(ax - bw / 2, bubbleTop, bw, bh, 4).fill(0xffffff);
    bubbleG.roundRect(ax - bw / 2, bubbleTop, bw, bh, 4).stroke({ width: 1.2, color: themeAccent, alpha: 0.4 });
    bubbleG
      .moveTo(ax - 3, bubbleTop + bh)
      .lineTo(ax, bubbleTop + bh + 4)
      .lineTo(ax + 3, bubbleTop + bh)
      .fill(0xffffff);
    room.addChild(bubbleG);
    bubbleText.position.set(ax, bubbleTop + bh - 8);
    room.addChild(bubbleText);
  }

  const workingSubs = subAgents.filter((sub) => sub.parentAgentId === agent.id && sub.status === "working");
  if (isWorking && workingSubs.length > 0) {
    const visibleSubs = workingSubs.slice(0, MAX_VISIBLE_SUB_CLONES_PER_AGENT);
    visibleSubs.forEach((sub, index) => {
      const sx = ax - 14 + index * 12;
      const sy = charFeetY - 3.5 + (index % 2) * 0.9;
      const cloneContainer = new Container();
      cloneContainer.position.set(sx, sy);

      const aura = new Graphics();
      aura.ellipse(0, 2.0, 8.1, 2.7).fill({ color: 0x1f2937, alpha: 0.12 });
      cloneContainer.addChild(aura);

      const cloneSpriteNum = (hashStr(`${sub.id}:clone`) % 13) + 1;
      const cloneFrames: Texture[] = [];
      for (let frame = 1; frame <= 3; frame++) {
        const key = `${cloneSpriteNum}-D-${frame}`;
        if (textures[key]) cloneFrames.push(textures[key]);
      }
      const baseTexture = cloneFrames[0];
      if (!baseTexture) return;
      const baseScale = (TARGET_CHAR_H / baseTexture.height) * 0.76;

      const cloneVisual = cloneFrames.length > 1 ? new AnimatedSprite(cloneFrames) : new Sprite(baseTexture);
      cloneVisual.anchor.set(0.5, 1);
      cloneVisual.scale.set(baseScale);
      cloneVisual.tint = 0xffffff;
      cloneVisual.alpha = 0.97;
      if (cloneVisual instanceof AnimatedSprite) cloneVisual.gotoAndStop((index + 1) % cloneFrames.length);
      cloneContainer.addChild(cloneVisual);

      const charIdx = room.children.indexOf(charContainer);
      if (charIdx >= 0) room.addChildAt(cloneContainer, charIdx);
      else room.addChild(cloneContainer);

      nextSubSnapshot.set(sub.id, { parentAgentId: agent.id, x: sx, y: sy });
      if (addedWorkingSubIds.has(sub.id)) {
        emitSubCloneSmokeBurst(room, subCloneBurstParticlesRef.current, sx, sy, "spawn");
        emitSubCloneFireworkBurst(room, subCloneBurstParticlesRef.current, sx, sy - 24);
        addedWorkingSubIds.delete(sub.id);
      }

      subCloneAnimItemsRef.current.push({
        container: cloneContainer,
        aura,
        cloneVisual,
        animated: cloneVisual instanceof AnimatedSprite ? cloneVisual : undefined,
        frameCount: cloneFrames.length,
        baseScale,
        baseX: sx,
        baseY: sy,
        phase: (hashStr(sub.id) % 360) / 57.2958 + index * 0.3,
        fireworkOffset: Math.abs(hashStr(`${sub.id}:firework`)) % SUB_CLONE_FIREWORK_INTERVAL,
      });
    });

    if (workingSubs.length > MAX_VISIBLE_SUB_CLONES_PER_AGENT) {
      const remain = workingSubs.length - MAX_VISIBLE_SUB_CLONES_PER_AGENT;
      const moreBg = new Graphics();
      moreBg.roundRect(ax + 18, deskY - 18, 18, 10, 2).fill({ color: 0x101722, alpha: 0.82 });
      room.addChild(moreBg);
      const moreTxt = new Text({
        text: `+${remain}`,
        style: new TextStyle({ fontSize: 6.5, fill: 0xe2e8f8, fontWeight: "bold", fontFamily: "monospace" }),
      });
      moreTxt.anchor.set(0.5, 0.5);
      moreTxt.position.set(ax + 27, deskY - 13);
      room.addChild(moreTxt);
    }
  }

  if (isOffline) {
    const zzz = new Text({ text: "💤", style: new TextStyle({ fontSize: 12 }) });
    zzz.anchor.set(0.5, 0.5);
    zzz.position.set(ax + 20, charFeetY - TARGET_CHAR_H / 2);
    room.addChild(zzz);
  }
}

import type { MutableRefObject } from "react";
import { Container, Graphics, Sprite, Text, TextStyle, type Application, type Texture } from "pixi.js";
import type { Agent } from "../../types";
import { localeName } from "../../i18n";
import type { CallbackSnapshot, BreakAnimItem } from "./buildScene-types";
import { BREAK_ROOM_H, TARGET_CHAR_H, type RoomTheme, type WallClockVisual } from "./model";
import { BREAK_CHAT_MESSAGES, BREAK_SPOTS, LOCALE_TEXT, type SupportedLocale, pickLocale } from "./themes-locale";
import {
  blendColor,
  contrastTextColor,
  drawAmbientGlow,
  drawBunting,
  drawCeilingLight,
  drawPictureFrame,
  drawRoomAtmosphere,
  drawRug,
  drawTiledFloor,
  drawTrashCan,
  drawWallClock,
  hashStr,
} from "./drawing-core";
import { drawPlant } from "./drawing-furniture-a";
import { drawCoffeeMachine, drawCoffeeTable, drawHighTable, drawSofa, drawVendingMachine } from "./drawing-furniture-b";

interface BuildBreakRoomParams {
  app: Application;
  textures: Record<string, Texture>;
  agents: Agent[];
  spriteMap: Map<string, number>;
  activeLocale: SupportedLocale;
  breakTheme: RoomTheme;
  isDark: boolean;
  breakRoomY: number;
  OFFICE_W: number;
  cbRef: MutableRefObject<CallbackSnapshot>;
  breakAnimItemsRef: MutableRefObject<BreakAnimItem[]>;
  breakBubblesRef: MutableRefObject<Container[]>;
  breakSteamParticlesRef: MutableRefObject<Container | null>;
  breakRoomRectRef: MutableRefObject<{ x: number; y: number; w: number; h: number } | null>;
  wallClocksRef: MutableRefObject<WallClockVisual[]>;
  agentPosRef: MutableRefObject<Map<string, { x: number; y: number }>>;
}

export function buildBreakRoom({
  app,
  textures,
  agents,
  spriteMap,
  activeLocale,
  breakTheme,
  isDark,
  breakRoomY,
  OFFICE_W,
  cbRef,
  breakAnimItemsRef,
  breakBubblesRef,
  breakSteamParticlesRef,
  breakRoomRectRef,
  wallClocksRef,
  agentPosRef,
}: BuildBreakRoomParams): void {
  const breakAgents = agents.filter((agent) => agent.status === "break");
  breakAnimItemsRef.current = [];
  breakBubblesRef.current = [];

  const breakRoom = new Container();
  const brx = 4;
  const bry = breakRoomY;
  const brw = OFFICE_W - 8;
  const brh = BREAK_ROOM_H;
  breakRoomRectRef.current = { x: brx, y: bry, w: brw, h: brh };

  const brFloor = new Graphics();
  drawTiledFloor(brFloor, brx, bry, brw, brh, breakTheme.floor1, breakTheme.floor2);
  breakRoom.addChild(brFloor);
  drawRoomAtmosphere(breakRoom, brx, bry, brw, brh, breakTheme.wall, breakTheme.accent);

  const brBorder = new Graphics();
  brBorder.roundRect(brx, bry, brw, brh, 3).stroke({ width: 2, color: breakTheme.wall });
  brBorder.roundRect(brx - 1, bry - 1, brw + 2, brh + 2, 4).stroke({ width: 1, color: breakTheme.accent, alpha: 0.25 });
  breakRoom.addChild(brBorder);

  drawAmbientGlow(breakRoom, brx + brw / 2, bry + brh / 2, brw * 0.3, breakTheme.accent, 0.05);
  drawCeilingLight(breakRoom, brx + brw / 3, bry + 6, breakTheme.accent);
  drawCeilingLight(breakRoom, brx + (brw * 2) / 3, bry + 6, breakTheme.accent);
  drawBunting(
    breakRoom,
    brx + 14,
    bry + 16,
    brw - 28,
    blendColor(0xb5d6cf, 0xffffff, 0.18),
    blendColor(0xdcb7bf, 0xffffff, 0.08),
    0.64,
  );

  const furnitureBaseX = brx + 16;
  drawCoffeeMachine(breakRoom, furnitureBaseX, bry + 20);
  drawPlant(breakRoom, furnitureBaseX + 30, bry + 38, 1);
  drawSofa(breakRoom, furnitureBaseX + 50, bry + 56, 0xc89da6);
  drawCoffeeTable(breakRoom, furnitureBaseX + 140, bry + 58);

  const furnitureRightX = brx + brw - 16;
  drawVendingMachine(breakRoom, furnitureRightX - 26, bry + 20);
  drawPlant(breakRoom, furnitureRightX - 36, bry + 38, 2);
  drawSofa(breakRoom, furnitureRightX - 120, bry + 56, 0x91bcae);
  drawHighTable(breakRoom, furnitureRightX - 170, bry + 24);

  drawPictureFrame(breakRoom, brx + brw / 2 - 8, bry + 14);
  wallClocksRef.current.push(drawWallClock(breakRoom, brx + brw / 2 + 30, bry + 18));
  drawTrashCan(breakRoom, furnitureBaseX + 24, bry + brh - 14);

  const brSignW = 84;
  const brSignBg = new Graphics();
  brSignBg.roundRect(brx + brw / 2 - brSignW / 2 + 1, bry - 3, brSignW, 18, 4).fill({ color: 0x000000, alpha: 0.12 });
  brSignBg.roundRect(brx + brw / 2 - brSignW / 2, bry - 4, brSignW, 18, 4).fill(breakTheme.accent);
  breakRoom.addChild(brSignBg);
  const breakSignTextColor = isDark ? 0xffffff : contrastTextColor(breakTheme.accent);
  const brSignTxt = new Text({
    text: pickLocale(activeLocale, LOCALE_TEXT.breakRoom),
    style: new TextStyle({
      fontSize: 9,
      fill: breakSignTextColor,
      fontWeight: "bold",
      fontFamily: "system-ui, sans-serif",
      dropShadow: isDark ? { alpha: 0.6, blur: 2, distance: 1, color: 0x000000 } : undefined,
    }),
  });
  brSignTxt.anchor.set(0.5, 0.5);
  brSignTxt.position.set(brx + brw / 2, bry + 5);
  breakRoom.addChild(brSignTxt);

  drawRug(breakRoom, brx + brw / 2, bry + brh / 2 + 10, brw * 0.5, brh * 0.45, breakTheme.accent);

  const steamContainer = new Container();
  breakRoom.addChild(steamContainer);
  breakSteamParticlesRef.current = steamContainer;

  breakAgents.forEach((agent, index) => {
    const spot = BREAK_SPOTS[index % BREAK_SPOTS.length];
    const seed = hashStr(agent.id);
    const offsetX = (seed % 7) - 3;
    const offsetY = ((seed % 5) - 2) * 0.6;

    const spotX = spot.x >= 0 ? brx + spot.x + offsetX : brx + brw - 16 + spot.x + offsetX;
    const spotY = bry + 100 + spot.y + offsetY;

    agentPosRef.current.set(agent.id, { x: spotX, y: spotY });

    const spriteNum = spriteMap.get(agent.id) ?? (seed % 13) + 1;
    const charContainer = new Container();
    charContainer.position.set(spotX, spotY);
    charContainer.eventMode = "static";
    charContainer.cursor = "pointer";
    charContainer.on("pointerdown", () => cbRef.current.onSelectAgent(agent));

    const dirKey = `${spriteNum}-${spot.dir}-1`;
    const fallbackKey = `${spriteNum}-D-1`;
    const texture = textures[dirKey] || textures[fallbackKey];

    if (texture) {
      const sprite = new Sprite(texture);
      sprite.anchor.set(0.5, 1);
      const scale = (TARGET_CHAR_H * 0.85) / sprite.texture.height;
      sprite.scale.set(scale);
      charContainer.addChild(sprite);
    } else {
      const fallback = new Text({ text: agent.avatar_emoji || "🤖", style: new TextStyle({ fontSize: 20 }) });
      fallback.anchor.set(0.5, 1);
      charContainer.addChild(fallback);
    }
    breakRoom.addChild(charContainer);

    breakAnimItemsRef.current.push({
      sprite: charContainer,
      baseX: spotX,
      baseY: spotY,
    });

    const coffeeEmoji = new Text({ text: "☕", style: new TextStyle({ fontSize: 10 }) });
    coffeeEmoji.anchor.set(0.5, 0.5);
    coffeeEmoji.position.set(spotX + 14, spotY - 10);
    breakRoom.addChild(coffeeEmoji);

    const nameTag = new Text({
      text: localeName(activeLocale, agent),
      style: new TextStyle({ fontSize: 22, fill: 0x4a3a2a, fontFamily: "system-ui, sans-serif" }),
    });
    nameTag.anchor.set(0.5, 0);
    const ntW = nameTag.width + 8;
    const tagY = spotY + 2 + (index % 4) * 36;
    const tagX = Math.max(brx + ntW / 2 + 4, Math.min(spotX, brx + brw - ntW / 2 - 4));
    const ntBg = new Graphics();
    ntBg.roundRect(tagX - ntW / 2, tagY, ntW, 34, 4).fill({ color: 0xffffff, alpha: 0.8 });
    breakRoom.addChild(ntBg);
    nameTag.position.set(tagX, tagY + 2);
    breakRoom.addChild(nameTag);
  });

  if (breakAgents.length > 0) {
    const phase = Math.floor(Date.now() / 4000);
    const speakerCount = Math.min(1, breakAgents.length);
    for (let speakerIndex = 0; speakerIndex < speakerCount; speakerIndex++) {
      const speakerIdx = (phase + speakerIndex) % breakAgents.length;
      const agent = breakAgents[speakerIdx];
      const spot = BREAK_SPOTS[speakerIdx % BREAK_SPOTS.length];
      const seed = hashStr(agent.id);
      const spotX = spot.x >= 0 ? brx + spot.x + ((seed % 7) - 3) : brx + brw - 16 + spot.x + ((seed % 7) - 3);
      const spotY = bry + 100 + spot.y + ((seed % 5) - 2) * 0.6;

      const chatPool = BREAK_CHAT_MESSAGES[activeLocale] || BREAK_CHAT_MESSAGES.ko;
      const msg = chatPool[(seed + phase) % chatPool.length];
      const bubbleText = new Text({
        text: msg,
        style: new TextStyle({ fontSize: 24, fill: 0x333333, fontFamily: "system-ui, sans-serif", wordWrap: true, wordWrapWidth: 240, breakWords: true }),
      });
      bubbleText.anchor.set(0.5, 1);
      const bw = bubbleText.width + 20;
      const bh = bubbleText.height + 16;
      const bubbleTop = Math.max(bry + 28, spotY - TARGET_CHAR_H * 0.85 - bh - 4);
      const bubbleX = Math.max(brx + bw / 2 + 8, Math.min(spotX, brx + brw - bw / 2 - 8));

      const bubbleG = new Graphics();
      bubbleG.roundRect(bubbleX - bw / 2, bubbleTop, bw, bh, 4).fill(0xfff8f0);
      bubbleG.roundRect(bubbleX - bw / 2, bubbleTop, bw, bh, 4).stroke({
        width: 1.2,
        color: breakTheme.accent,
        alpha: 0.5,
      });
      bubbleG
        .moveTo(spotX - 3, bubbleTop + bh)
        .lineTo(spotX, bubbleTop + bh + 4)
        .lineTo(spotX + 3, bubbleTop + bh)
        .fill(0xfff8f0);
      breakRoom.addChild(bubbleG);
      bubbleText.position.set(bubbleX, bubbleTop + bh - 8);
      breakRoom.addChild(bubbleText);

      const bubbleContainer = new Container();
      bubbleContainer.addChild(bubbleG);
      breakRoom.removeChild(bubbleG);
      breakRoom.removeChild(bubbleText);
      bubbleContainer.addChild(bubbleG);
      bubbleContainer.addChild(bubbleText);
      breakRoom.addChild(bubbleContainer);
      breakBubblesRef.current.push(bubbleContainer);
    }
  }

  app.stage.addChild(breakRoom);
}

import { useEffect, type MutableRefObject } from "react";
import { AnimatedSprite, Container, Graphics, Text, TextStyle, type Texture } from "pixi.js";
import type { Agent, CeoOfficeCall, CrossDeptDelivery, MeetingPresence } from "../../types";
import { hashStr } from "./drawing-core";
import { type Delivery, destroyNode, trackProcessedId } from "./model";
import {
  LOCALE_TEXT,
  paintMeetingBadge,
  pickLocale,
  resolveMeetingDecision,
  type SupportedLocale,
} from "./themes-locale";

interface MeetingPresenceSyncParams {
  meetingPresence?: MeetingPresence[];
  language: SupportedLocale;
  sceneRevision: number;
  deliveryLayerRef: MutableRefObject<Container | null>;
  texturesRef: MutableRefObject<Record<string, Texture>>;
  ceoMeetingSeatsRef: MutableRefObject<Array<{ x: number; y: number }>>;
  deliveriesRef: MutableRefObject<Delivery[]>;
  spriteMapRef: MutableRefObject<Map<string, number>>;
}

export function useMeetingPresenceSync({
  meetingPresence,
  language,
  sceneRevision,
  deliveryLayerRef,
  texturesRef,
  ceoMeetingSeatsRef,
  deliveriesRef,
  spriteMapRef,
}: MeetingPresenceSyncParams): void {
  useEffect(() => {
    const dlLayer = deliveryLayerRef.current;
    const textures = texturesRef.current;
    const seats = ceoMeetingSeatsRef.current;
    if (!dlLayer || seats.length === 0) return;

    const now = Date.now();
    const rows = (meetingPresence ?? []).filter((row) => row.until >= now);
    const activeByAgent = new Map(rows.map((row) => [row.agent_id, row]));

    for (const row of rows) {
      const seat = seats[row.seat_index % seats.length];
      if (!seat) continue;
      const decision = resolveMeetingDecision(row.phase, row.decision);

      const existing = deliveriesRef.current.find((delivery) => {
        return delivery.agentId === row.agent_id && delivery.holdAtSeat && !delivery.sprite.destroyed;
      });

      if (existing) {
        existing.meetingSeatIndex = row.seat_index;
        existing.holdUntil = row.until;
        existing.toX = seat.x;
        existing.toY = seat.y;
        existing.arrived = true;
        existing.progress = 1;
        existing.seatedPoseApplied = false;
        existing.meetingDecision = decision;
        existing.sprite.position.set(seat.x, seat.y);
        existing.sprite.alpha = 1;
        if (existing.badgeGraphics && existing.badgeText) {
          paintMeetingBadge(existing.badgeGraphics, existing.badgeText, language, row.phase, decision);
        }
        continue;
      }

      const spriteNum = spriteMapRef.current.get(row.agent_id) ?? (hashStr(row.agent_id) % 13) + 1;
      const actor = new Container();
      const frames: Texture[] = [];

      for (let frame = 1; frame <= 3; frame++) {
        const key = `${spriteNum}-D-${frame}`;
        if (textures[key]) frames.push(textures[key]);
      }

      if (frames.length > 0) {
        const animSprite = new AnimatedSprite(frames);
        animSprite.anchor.set(0.5, 1);
        const scale = 44 / animSprite.texture.height;
        animSprite.scale.set(scale);
        animSprite.gotoAndStop(0);
        actor.addChild(animSprite);
      } else {
        const fallback = new Text({ text: "🧑‍💼", style: new TextStyle({ fontSize: 20 }) });
        fallback.anchor.set(0.5, 1);
        actor.addChild(fallback);
      }

      const badge = new Graphics();
      actor.addChild(badge);
      const badgeText = new Text({
        text: "",
        style: new TextStyle({ fontSize: 14, fill: 0x111111, fontWeight: "bold", fontFamily: "system-ui, sans-serif" }),
      });
      badgeText.anchor.set(0.5, 0.5);
      badgeText.position.set(0, 10.5);
      actor.addChild(badgeText);
      paintMeetingBadge(badge, badgeText, language, row.phase, decision);

      actor.position.set(seat.x, seat.y);
      dlLayer.addChild(actor);
      deliveriesRef.current.push({
        sprite: actor,
        fromX: seat.x,
        fromY: seat.y,
        toX: seat.x,
        toY: seat.y,
        progress: 1,
        speed: 0.0048,
        type: "walk",
        agentId: row.agent_id,
        holdAtSeat: true,
        holdUntil: row.until,
        arrived: true,
        meetingSeatIndex: row.seat_index,
        meetingDecision: decision,
        badgeGraphics: badge,
        badgeText,
      });
    }

    for (let i = deliveriesRef.current.length - 1; i >= 0; i--) {
      const delivery = deliveriesRef.current[i];
      if (!delivery.holdAtSeat || !delivery.agentId || !delivery.arrived) continue;
      if (activeByAgent.has(delivery.agentId)) continue;
      destroyNode(delivery.sprite);
      deliveriesRef.current.splice(i, 1);
    }
  }, [
    meetingPresence,
    language,
    sceneRevision,
    deliveryLayerRef,
    texturesRef,
    ceoMeetingSeatsRef,
    deliveriesRef,
    spriteMapRef,
  ]);
}

interface CrossDeptDeliveryAnimationParams {
  crossDeptDeliveries?: CrossDeptDelivery[];
  language: SupportedLocale;
  onCrossDeptDeliveryProcessed?: (id: string) => void;
  deliveryLayerRef: MutableRefObject<Container | null>;
  texturesRef: MutableRefObject<Record<string, Texture>>;
  agentPosRef: MutableRefObject<Map<string, { x: number; y: number }>>;
  spriteMapRef: MutableRefObject<Map<string, number>>;
  processedCrossDeptRef: MutableRefObject<Set<string>>;
  deliveriesRef: MutableRefObject<Delivery[]>;
}

export function useCrossDeptDeliveryAnimations({
  crossDeptDeliveries,
  language,
  onCrossDeptDeliveryProcessed,
  deliveryLayerRef,
  texturesRef,
  agentPosRef,
  spriteMapRef,
  processedCrossDeptRef,
  deliveriesRef,
}: CrossDeptDeliveryAnimationParams): void {
  useEffect(() => {
    if (!crossDeptDeliveries?.length) return;
    const dlLayer = deliveryLayerRef.current;
    const textures = texturesRef.current;
    if (!dlLayer) return;

    for (const delivery of crossDeptDeliveries) {
      if (processedCrossDeptRef.current.has(delivery.id)) continue;
      trackProcessedId(processedCrossDeptRef.current, delivery.id);

      const fromPos = agentPosRef.current.get(delivery.fromAgentId);
      const toPos = agentPosRef.current.get(delivery.toAgentId);
      if (!fromPos || !toPos) {
        onCrossDeptDeliveryProcessed?.(delivery.id);
        continue;
      }

      const actor = new Container();
      const spriteNum = spriteMapRef.current.get(delivery.fromAgentId) ?? (hashStr(delivery.fromAgentId) % 13) + 1;
      const frames: Texture[] = [];
      for (let frame = 1; frame <= 3; frame++) {
        const key = `${spriteNum}-D-${frame}`;
        if (textures[key]) frames.push(textures[key]);
      }

      if (frames.length > 0) {
        const animSprite = new AnimatedSprite(frames);
        animSprite.anchor.set(0.5, 1);
        const scale = 44 / animSprite.texture.height;
        animSprite.scale.set(scale);
        animSprite.animationSpeed = 0.12;
        animSprite.play();
        animSprite.position.set(0, 0);
        actor.addChild(animSprite);
      } else {
        const fallback = new Text({ text: "🧑‍💼", style: new TextStyle({ fontSize: 20 }) });
        fallback.anchor.set(0.5, 1);
        actor.addChild(fallback);
      }

      const docHolder = new Container();
      const docEmoji = new Text({ text: "📋", style: new TextStyle({ fontSize: 13 }) });
      docEmoji.anchor.set(0.5, 0.5);
      docHolder.addChild(docEmoji);
      docHolder.position.set(0, -50);
      actor.addChild(docHolder);

      const badge = new Graphics();
      badge.roundRect(-16, 3, 32, 13, 4).fill({ color: 0xf59e0b, alpha: 0.9 });
      badge.roundRect(-16, 3, 32, 13, 4).stroke({ width: 1, color: 0xd97706, alpha: 0.5 });
      actor.addChild(badge);

      const badgeText = new Text({
        text: pickLocale(language, LOCALE_TEXT.collabBadge),
        style: new TextStyle({ fontSize: 14, fill: 0x000000, fontWeight: "bold", fontFamily: "system-ui, sans-serif" }),
      });
      badgeText.anchor.set(0.5, 0.5);
      badgeText.position.set(0, 9.5);
      actor.addChild(badgeText);

      actor.position.set(fromPos.x, fromPos.y);
      dlLayer.addChild(actor);

      deliveriesRef.current.push({
        sprite: actor,
        fromX: fromPos.x,
        fromY: fromPos.y,
        toX: toPos.x,
        toY: toPos.y,
        progress: 0,
        speed: 0.005,
        type: "walk",
      });

      onCrossDeptDeliveryProcessed?.(delivery.id);
    }
  }, [
    crossDeptDeliveries,
    language,
    onCrossDeptDeliveryProcessed,
    deliveryLayerRef,
    texturesRef,
    agentPosRef,
    spriteMapRef,
    processedCrossDeptRef,
    deliveriesRef,
  ]);
}

interface CeoOfficeCallAnimationParams {
  ceoOfficeCalls?: CeoOfficeCall[];
  agents: Agent[];
  language: SupportedLocale;
  onCeoOfficeCallProcessed?: (id: string) => void;
  deliveryLayerRef: MutableRefObject<Container | null>;
  texturesRef: MutableRefObject<Record<string, Texture>>;
  ceoMeetingSeatsRef: MutableRefObject<Array<{ x: number; y: number }>>;
  deliveriesRef: MutableRefObject<Delivery[]>;
  spriteMapRef: MutableRefObject<Map<string, number>>;
  agentPosRef: MutableRefObject<Map<string, { x: number; y: number }>>;
  processedCeoOfficeRef: MutableRefObject<Set<string>>;
}

export function useCeoOfficeCallAnimations({
  ceoOfficeCalls,
  agents,
  language,
  onCeoOfficeCallProcessed,
  deliveryLayerRef,
  texturesRef,
  ceoMeetingSeatsRef,
  deliveriesRef,
  spriteMapRef,
  agentPosRef,
  processedCeoOfficeRef,
}: CeoOfficeCallAnimationParams): void {
  useEffect(() => {
    if (!ceoOfficeCalls?.length) return;
    const dlLayer = deliveryLayerRef.current;
    const textures = texturesRef.current;
    if (!dlLayer) return;

    const pickLine = (call: CeoOfficeCall) => {
      const provided = call.line?.trim();
      if (provided) return provided;
      const pool =
        call.phase === "review"
          ? pickLocale(language, LOCALE_TEXT.reviewLines)
          : pickLocale(language, LOCALE_TEXT.kickoffLines);
      return pool[hashStr(`${call.fromAgentId}-${call.id}`) % pool.length];
    };

    const renderSpeechBubble = (x: number, y: number, phase: "kickoff" | "review", line: string) => {
      const bubble = new Container();
      const bubbleText = new Text({
        text: line,
        style: new TextStyle({
          fontSize: 24,
          fill: 0x2b2b2b,
          fontFamily: "system-ui, sans-serif",
          wordWrap: true,
          wordWrapWidth: 260,
          breakWords: true,
        }),
      });
      bubbleText.anchor.set(0.5, 1);
      const bubbleW = bubbleText.width + 24;
      const bubbleH = bubbleText.height + 18;
      const bubbleY = -62;

      const bubbleBody = new Graphics();
      bubbleBody.roundRect(-bubbleW / 2, bubbleY - bubbleH, bubbleW, bubbleH, 4).fill(0xfff8e8);
      bubbleBody.roundRect(-bubbleW / 2, bubbleY - bubbleH, bubbleW, bubbleH, 4).stroke({
        width: 1,
        color: phase === "review" ? 0x34d399 : 0xf59e0b,
        alpha: 0.6,
      });
      bubbleBody
        .moveTo(-3, bubbleY)
        .lineTo(0, bubbleY + 4)
        .lineTo(3, bubbleY)
        .fill(0xfff8e8);
      bubble.addChild(bubbleBody);
      bubbleText.position.set(0, bubbleY - 9);
      bubble.addChild(bubbleText);

      bubble.position.set(x, y - 6);
      dlLayer.addChild(bubble);

      setTimeout(() => {
        destroyNode(bubble);
      }, 2800);
    };

    for (const call of ceoOfficeCalls) {
      if (processedCeoOfficeRef.current.has(call.id)) continue;

      if (call.action === "dismiss") {
        trackProcessedId(processedCeoOfficeRef.current, call.id);
        for (let i = deliveriesRef.current.length - 1; i >= 0; i--) {
          const delivery = deliveriesRef.current[i];
          if (delivery.agentId === call.fromAgentId && delivery.holdAtSeat) {
            destroyNode(delivery.sprite);
            deliveriesRef.current.splice(i, 1);
          }
        }
        onCeoOfficeCallProcessed?.(call.id);
        continue;
      }

      const seats = ceoMeetingSeatsRef.current;
      const seat = seats.length > 0 ? seats[call.seatIndex % seats.length] : null;
      if (!seat) continue;

      if (call.action === "speak") {
        trackProcessedId(processedCeoOfficeRef.current, call.id);
        const line = pickLine(call);
        const decision = resolveMeetingDecision(call.phase, call.decision, line);
        renderSpeechBubble(seat.x, seat.y, call.phase, line);
        if (call.phase === "review") {
          const attendee = deliveriesRef.current.find((delivery) => {
            return delivery.agentId === call.fromAgentId && delivery.holdAtSeat && !delivery.sprite.destroyed;
          });
          if (attendee) {
            attendee.meetingDecision = decision;
            if (attendee.badgeGraphics && attendee.badgeText) {
              paintMeetingBadge(attendee.badgeGraphics, attendee.badgeText, language, call.phase, decision);
            }
          }
        }
        onCeoOfficeCallProcessed?.(call.id);
        continue;
      }

      const fromPos = agentPosRef.current.get(call.fromAgentId);
      if (!fromPos) continue;

      trackProcessedId(processedCeoOfficeRef.current, call.id);
      const actor = new Container();
      const spriteNum = spriteMapRef.current.get(call.fromAgentId) ?? (hashStr(call.fromAgentId) % 13) + 1;
      const frames: Texture[] = [];

      for (let frame = 1; frame <= 3; frame++) {
        const key = `${spriteNum}-D-${frame}`;
        if (textures[key]) frames.push(textures[key]);
      }

      if (frames.length > 0) {
        const animSprite = new AnimatedSprite(frames);
        animSprite.anchor.set(0.5, 1);
        const scale = 44 / animSprite.texture.height;
        animSprite.scale.set(scale);
        animSprite.animationSpeed = 0.12;
        animSprite.play();
        actor.addChild(animSprite);
      } else {
        const fallback = new Text({ text: "🧑‍💼", style: new TextStyle({ fontSize: 20 }) });
        fallback.anchor.set(0.5, 1);
        actor.addChild(fallback);
      }

      const badge = new Graphics();
      actor.addChild(badge);
      const decision = resolveMeetingDecision(call.phase, call.decision, call.line);
      const badgeText = new Text({
        text: "",
        style: new TextStyle({ fontSize: 14, fill: 0x111111, fontWeight: "bold", fontFamily: "system-ui, sans-serif" }),
      });
      badgeText.anchor.set(0.5, 0.5);
      badgeText.position.set(0, 10.5);
      actor.addChild(badgeText);
      paintMeetingBadge(badge, badgeText, language, call.phase, decision);

      actor.position.set(fromPos.x, fromPos.y);
      dlLayer.addChild(actor);

      for (let i = deliveriesRef.current.length - 1; i >= 0; i--) {
        const delivery = deliveriesRef.current[i];
        if (delivery.agentId !== call.fromAgentId) continue;
        destroyNode(delivery.sprite);
        deliveriesRef.current.splice(i, 1);
      }

      deliveriesRef.current.push({
        sprite: actor,
        fromX: fromPos.x,
        fromY: fromPos.y,
        toX: seat.x,
        toY: seat.y,
        progress: 0,
        speed: 0.0048,
        type: "walk",
        agentId: call.fromAgentId,
        holdAtSeat: true,
        holdUntil: call.holdUntil ?? Date.now() + 600_000,
        meetingSeatIndex: call.seatIndex,
        meetingDecision: decision,
        badgeGraphics: badge,
        badgeText,
      });

      onCeoOfficeCallProcessed?.(call.id);
    }
  }, [
    ceoOfficeCalls,
    onCeoOfficeCallProcessed,
    language,
    agents,
    deliveryLayerRef,
    texturesRef,
    ceoMeetingSeatsRef,
    deliveriesRef,
    spriteMapRef,
    agentPosRef,
    processedCeoOfficeRef,
  ]);
}
